contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: fund is Ether to deposit before withdrawing
    function run(uint fund) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (fund)); require(fund <= 1000000000000000000000000000000);
        // ensure this contract can fund the deposit call
        require(address(this).balance >= fund);

        // record balance recorded for this test-contract before any operations
        uint beforeUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBal = address(c).balance;

        // try to add funds to c under this contract's address
        bool addReverted;
        c.addToBalance{value: fund}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            addReverted = true;
        } else {
            addReverted = false;
        }

        // read recorded balance after deposit attempt
        uint midUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint midContractBal = address(c).balance;

        // attempt withdrawal and record whether it reverted
        bool withdrawReverted;
        c.withdrawBalance(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        // observed values after withdraw attempt
        uint afterUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBal = address(c).balance;

        // General invariant:
        // If withdrawBalance succeeded then the recorded user balance becomes zero
        // and the contract's balance did not decrease by more than the user's balance just before withdrawal.
        // (i.e., contract cannot lose more Ether than it recorded for that user in getBalance)
        assert(withdrawReverted || (afterUser == 0 && (beforeUser == 0 ? afterContractBal <= midContractBal : midContractBal - afterContractBal <= midUser)));
    }

    // allow receiving Ether so the test contract can fund calls and receive refunds
    receive() external payable {}
}

