// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 fund) internal {
        fund = bound(fund, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= fund);
        uint256 beforeUser;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeUser = __r; } catch { return; }
        uint beforeContractBal = address(c).balance;
        bool addReverted;
        try c.addToBalance{value: fund}() {
            addReverted = false;
        } catch {
            addReverted = true;
        }
        uint256 midUser;
        try c.getBalance(address(this)) returns (uint256 __r) { midUser = __r; } catch { return; }
        uint midContractBal = address(c).balance;
        bool withdrawReverted;
        try c.withdrawBalance() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint256 afterUser;
        try c.getBalance(address(this)) returns (uint256 __r) { afterUser = __r; } catch { return; }
        uint afterContractBal = address(c).balance;
        assertTrue(withdrawReverted || (afterUser == 0 && (beforeUser == 0 ? afterContractBal <= midContractBal : midContractBal - afterContractBal <= midUser)));
    }

    function testFuzz_run(uint256 fund) public {
        _run(fund);
    }

    receive() external payable {}
}
